 "content": "def transform(grid):
    """Stamp every copy of the marked shape onto matching all-zero positions."""
    h, w = len(grid), len(grid[0])
    markers = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v not in (0, 1, 6)]
    if not markers:
        return [row[:] for row in grid]
    color = markers[0][2]
    shape = [(r, c) for r, c, v in markers if v == color]
    minr = min(r for r, c in shape); maxr = max(r for r, c in shape)
    minc = min(c for r, c in shape); maxc = max(c for r, c in shape)
    shape = [(r-minr, c-minc) for r, c in shape]
    out = [row[:] for row in grid]
    for dr in range(h - (maxr-minr+1) + 1):
        for dc in range(w - (maxc-minc+1) + 1):
            if all(grid[dr+r][dc+c] == 0 for r, c in shape):
                for r, c in shape:
                    out[dr+r][dc+c] = color
    return out
